import (
	"fmt"
)

resp, err := client.GiftCards().ListGiftCards(ctx, map[string]any{"email": "jane.doe@example.com", "is_active": true}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["gift_cards"].([]any) {
	giftCard := row.(map[string]any)
	fmt.Println(giftCard["id"], giftCard["code"], giftCard["balance"], giftCard["initial_amount"], giftCard["is_active"])
}
pagination := body["pagination"].(map[string]any)
fmt.Println(pagination["total"], pagination["has_next"])
